def test_sse_validation():
    # Test case 1: Multi-line event
    try:
        ServerSentEvent(event="multi\nline")
        print("FAIL: Multi-line event did not raise error.")
    except ValueError as e:
        print(f"PASS: Multi-line event raised expected error: {e}")

    # Test case 2: Multi-line id
    try:
        ServerSentEvent(id="line1\nline2")
        print("FAIL: Multi-line id did not raise error.")
    except ValueError as e:
        print(f"PASS: Multi-line id raised expected error: {e}")

    # Test case 3: Null byte in id
    try:
        ServerSentEvent(id="test\0")
        print("FAIL: Null byte in id did not raise error.")
    except ValueError as e:
        print(f"PASS: Null byte in id raised expected error: {e}")

    # Test case 4: Valid input
    try:
        ServerSentEvent(event="valid", id="123")
        print("PASS: Valid input passed validation.")
    except ValueError as e:
        print(f"FAIL: Valid input raised unexpected error: {e}")

if __name__ == "__main__":
